(n.target_scope = 'TENANT'
 or (n.target_scope = 'USER' and n.target_user_id = #{userId})

     or (n.target_scope = 'ROLE' and n.target_role_id in

             #{roleId}

     )

)

(n.target_scope = 'TENANT'
 or (n.target_scope = 'USER' and n.target_user_id = #{query.userId})

     or (n.target_scope = 'ROLE' and n.target_role_id in

             #{roleId}

     )

)

        n.tenant_id = #{query.tenantId}
        and n.deleted = 0

	            and (
	                n.created_by = #{query.userId}
	                or 
	            )


            and (n.title like concat('%', #{query.keyword}, '%') or n.content like concat('%', #{query.keyword}, '%'))


            and n.notice_type = #{query.messageType}


            and n.target_scope = #{query.targetScope}


            and n.source_type = #{query.sourceType}


            and n.publish_status = #{query.publishStatus}


            and n.published_at >= #{query.publishedAtStart}


            and n.published_at <= #{query.publishedAtEnd}

mapper.select:
select 
from msg_notice n force index (idx_msg_notice_visible_recent)

where n.tenant_id = #{tenantId}
  and n.deleted = 0
  and n.publish_status = 'PUBLISHED'
  and 
order by n.id desc
limit #{limit} offset #{offset}

select count(*)
from (
    select n.id
    from msg_notice n force index (idx_msg_notice_visible_recent)
    where n.tenant_id = #{tenantId}
      and n.deleted = 0
      and n.publish_status = 'PUBLISHED'
      and 
      and not exists (
            select 1
            from msg_notice_read r
            where r.notice_id = n.id
              and r.tenant_id = n.tenant_id
              and r.user_id = #{userId}
              and r.deleted = 0
      )
    limit #{limit}
) unread_candidates


select count(*)
from (
    select n.id
    from msg_notice n force index (idx_msg_notice_visible_recent)
    where 
    limit #{query.countLimit}
) archive_candidates

select 
from msg_notice n

where n.tenant_id = #{tenantId}
  and n.id = #{noticeId}
  and n.deleted = 0
limit 1
